-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the reservoircalc capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- reservoircalc / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e96cc7d1c266542be41a2e08cf95ad8f' and fields = '[{"key": "oil_cells", "tol": 0, "unit": "count", "label": "Oil-bearing grid cells", "expected": 169}, {"key": "max_oil_column_m", "tol": 0.1, "unit": "m", "label": "Maximum oil column", "expected": 20.2818603515625}, {"key": "grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "Gross rock volume", "expected": 22.26903564453125}, {"key": "pore_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Pore volume", "expected": 3.563045809312045}, {"key": "hcpv_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Hydrocarbon pore volume", "expected": 2.3159797972902343}, {"key": "stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP", "expected": 12.139208107496763}]'::jsonb then 'old'
              when md5(prompt) = '4bc947fef7483edc3eef1d3fff8cc179' and fields = '[{"key": "oil_cells", "tol": 0, "unit": "count", "label": "Oil-bearing grid cells", "expected": 169}, {"key": "max_oil_column_m", "tol": 0.1, "unit": "m", "label": "Maximum oil column", "expected": 20.2818603515625}, {"key": "grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "Gross rock volume", "expected": 22.26903564453125}, {"key": "pore_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Pore volume", "expected": 3.563045809312045}, {"key": "hcpv_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Hydrocarbon pore volume", "expected": 2.3159797972902343}, {"key": "stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP", "expected": 12.139208107496763}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/beginner matches neither its published form (prompt md5 e96cc7d1c266542be41a2e08cf95ad8f) nor its W1 form (prompt md5 4bc947fef7483edc3eef1d3fff8cc179), with the fields this file was generated against';
  end if;

  -- reservoircalc / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '526459ac1b53c4ad2d2dac5f0ac493af' and fields = '[{"key": "west_cells", "tol": 0, "unit": "count", "label": "West block: oil-bearing cells", "expected": 117}, {"key": "east_cells", "tol": 0, "unit": "count", "label": "East block: oil-bearing cells", "expected": 52}, {"key": "west_grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "West block: gross rock volume", "expected": 18.079852294921874}, {"key": "east_grv_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "East block: gross rock volume", "expected": 4.189183349609375}, {"key": "west_stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "West block: STOIIP", "expected": 9.85561714769438}, {"key": "east_stoiip_mmstb", "tol": 0.02, "unit": "MMstb", "label": "East block: STOIIP", "expected": 2.2835909598023787}]'::jsonb then 'old'
              when md5(prompt) = 'de9376047847924f40fa355df6d41e97' and fields = '[{"key": "west_cells", "tol": 0, "unit": "count", "label": "West block: oil-bearing cells", "expected": 117}, {"key": "east_cells", "tol": 0, "unit": "count", "label": "East block: oil-bearing cells", "expected": 52}, {"key": "west_grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "West block: gross rock volume", "expected": 18.079852294921874}, {"key": "east_grv_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "East block: gross rock volume", "expected": 4.189183349609375}, {"key": "west_stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "West block: STOIIP", "expected": 9.85561714769438}, {"key": "east_stoiip_mmstb", "tol": 0.02, "unit": "MMstb", "label": "East block: STOIIP", "expected": 2.2835909598023787}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/intermediate matches neither its published form (prompt md5 526459ac1b53c4ad2d2dac5f0ac493af) nor its W1 form (prompt md5 de9376047847924f40fa355df6d41e97), with the fields this file was generated against';
  end if;

  -- reservoircalc / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'abdf2a3de03f2eaa7bbf46ddca55070e' and fields = '[{"key": "phi_at_p1", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at P-1", "expected": 0.20714187889686578}, {"key": "phi_mean_oil", "tol": 0.0002, "unit": "v/v", "label": "Mean trend porosity over oil nodes", "expected": 0.20936760570720417}, {"key": "pore_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "Pore volume, trend model", "expected": 3.7558468705687864}, {"key": "hcpv_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "HCPV, trend model", "expected": 2.4413004882563025}, {"key": "stoiip_trend_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP, trend model", "expected": 12.79607650919541}, {"key": "stoiip_delta_mmstb", "tol": 0.02, "unit": "MMstb", "label": "STOIIP added over the constant model", "expected": 0.656868401698647}]'::jsonb then 'old'
              when md5(prompt) = 'd215a0b9b79c54fa53d8069ba84a160f' and fields = '[{"key": "phi_at_p1", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at P-1", "expected": 0.20714187889686578}, {"key": "phi_mean_oil", "tol": 0.0002, "unit": "v/v", "label": "Mean trend porosity over oil nodes", "expected": 0.20936760570720417}, {"key": "pore_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "Pore volume, trend model", "expected": 3.7558468705687864}, {"key": "hcpv_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "HCPV, trend model", "expected": 2.4413004882563025}, {"key": "stoiip_trend_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP, trend model", "expected": 12.79607650919541}, {"key": "stoiip_delta_mmstb", "tol": 0.02, "unit": "MMstb", "label": "STOIIP added over the constant model", "expected": 0.656868401698647}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/advanced matches neither its published form (prompt md5 abdf2a3de03f2eaa7bbf46ddca55070e) nor its W1 form (prompt md5 d215a0b9b79c54fa53d8069ba84a160f), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book reservoircalc: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book reservoircalc refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Set the oil-water contact to 1560 m and read the volumetrics panel: report the oil-bearing cell count, the maximum oil column, the gross rock volume, the pore volume, the hydrocarbon pore volume and the STOIIP at the given properties (NTG 0.8, porosity 0.20, Sw 0.35, Bo 1.2).',
           fields = '[{"key": "oil_cells", "tol": 0, "unit": "count", "label": "Oil-bearing grid cells", "expected": 169}, {"key": "max_oil_column_m", "tol": 0.1, "unit": "m", "label": "Maximum oil column", "expected": 20.2818603515625}, {"key": "grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "Gross rock volume", "expected": 22.26903564453125}, {"key": "pore_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Pore volume", "expected": 3.563045809312045}, {"key": "hcpv_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Hydrocarbon pore volume", "expected": 2.3159797972902343}, {"key": "stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP", "expected": 12.139208107496763}]'::jsonb
     where app_slug = 'reservoircalc' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '4bc947fef7483edc3eef1d3fff8cc179' and fields = '[{"key": "oil_cells", "tol": 0, "unit": "count", "label": "Oil-bearing grid cells", "expected": 169}, {"key": "max_oil_column_m", "tol": 0.1, "unit": "m", "label": "Maximum oil column", "expected": 20.2818603515625}, {"key": "grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "Gross rock volume", "expected": 22.26903564453125}, {"key": "pore_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Pore volume", "expected": 3.563045809312045}, {"key": "hcpv_mm3", "tol": 0.01, "unit": "10^6 m3", "label": "Hydrocarbon pore volume", "expected": 2.3159797972902343}, {"key": "stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP", "expected": 12.139208107496763}]'::jsonb) from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. A sealing fault at x = 1800 m splits the accumulation into a west and an east block. At the 1560 m contact, read the per-block panel: cell counts, gross rock volumes and STOIIP for each block. The two blocks must sum to the field total you booked at the Associate tier.',
           fields = '[{"key": "west_cells", "tol": 0, "unit": "count", "label": "West block: oil-bearing cells", "expected": 117}, {"key": "east_cells", "tol": 0, "unit": "count", "label": "East block: oil-bearing cells", "expected": 52}, {"key": "west_grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "West block: gross rock volume", "expected": 18.079852294921874}, {"key": "east_grv_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "East block: gross rock volume", "expected": 4.189183349609375}, {"key": "west_stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "West block: STOIIP", "expected": 9.85561714769438}, {"key": "east_stoiip_mmstb", "tol": 0.02, "unit": "MMstb", "label": "East block: STOIIP", "expected": 2.2835909598023787}]'::jsonb
     where app_slug = 'reservoircalc' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'de9376047847924f40fa355df6d41e97' and fields = '[{"key": "west_cells", "tol": 0, "unit": "count", "label": "West block: oil-bearing cells", "expected": 117}, {"key": "east_cells", "tol": 0, "unit": "count", "label": "East block: oil-bearing cells", "expected": 52}, {"key": "west_grv_mm3", "tol": 0.05, "unit": "10^6 m3", "label": "West block: gross rock volume", "expected": 18.079852294921874}, {"key": "east_grv_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "East block: gross rock volume", "expected": 4.189183349609375}, {"key": "west_stoiip_mmstb", "tol": 0.05, "unit": "MMstb", "label": "West block: STOIIP", "expected": 9.85561714769438}, {"key": "east_stoiip_mmstb", "tol": 0.02, "unit": "MMstb", "label": "East block: STOIIP", "expected": 2.2835909598023787}]'::jsonb) from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Replace the constant porosity with a per-node property grid: fit a porosity trend surface to the six well values (0.22, 0.19, 0.23, 0.17, 0.21, 0.22 for Ekene-1 to Ekene-6) with the population engine and rerun the volumetrics at the 1560 m contact. Read the panel: the trend porosity at prospect P-1 and its mean over the oil-bearing nodes, the pore volume and HCPV, the STOIIP, and how much the trend model adds over the constant-porosity booking.',
           fields = '[{"key": "phi_at_p1", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at P-1", "expected": 0.20714187889686578}, {"key": "phi_mean_oil", "tol": 0.0002, "unit": "v/v", "label": "Mean trend porosity over oil nodes", "expected": 0.20936760570720417}, {"key": "pore_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "Pore volume, trend model", "expected": 3.7558468705687864}, {"key": "hcpv_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "HCPV, trend model", "expected": 2.4413004882563025}, {"key": "stoiip_trend_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP, trend model", "expected": 12.79607650919541}, {"key": "stoiip_delta_mmstb", "tol": 0.02, "unit": "MMstb", "label": "STOIIP added over the constant model", "expected": 0.656868401698647}]'::jsonb
     where app_slug = 'reservoircalc' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book reservoircalc refused: reservoircalc/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd215a0b9b79c54fa53d8069ba84a160f' and fields = '[{"key": "phi_at_p1", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at P-1", "expected": 0.20714187889686578}, {"key": "phi_mean_oil", "tol": 0.0002, "unit": "v/v", "label": "Mean trend porosity over oil nodes", "expected": 0.20936760570720417}, {"key": "pore_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "Pore volume, trend model", "expected": 3.7558468705687864}, {"key": "hcpv_trend_mm3", "tol": 0.02, "unit": "10^6 m3", "label": "HCPV, trend model", "expected": 2.4413004882563025}, {"key": "stoiip_trend_mmstb", "tol": 0.05, "unit": "MMstb", "label": "STOIIP, trend model", "expected": 12.79607650919541}, {"key": "stoiip_delta_mmstb", "tol": 0.02, "unit": "MMstb", "label": "STOIIP added over the constant model", "expected": 0.656868401698647}]'::jsonb) from public.academy_capstones where app_slug = 'reservoircalc' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book reservoircalc refused: reservoircalc/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book reservoircalc: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
